use system.result
use system.string
// Represents a filesystem operation error.
@non_exhaustive
public enum FsError
    NotFound(String)
    PermissionDenied(String)
    AlreadyExists(String)
    NotADirectory(String)
    InvalidData(String)
    Other(String)
// Filesystem capability class. Acquire a handle with `let fs = Fs()` to access filesystem operations.
public class Fs
    // Checks whether a file or directory exists at the given path.
    public fn exists(path String) bool
    // Reads the entire contents of a file into a string.
    public fn read_file(path String) Result<String, FsError>
    // Writes the given contents to a file, truncating if it exists.
    public fn write_file(path String, contents String) Result<int, FsError>
    // Appends the given contents to a file, creating it if it doesn't exist.
    public fn append_file(path String, contents String) Result<int, FsError>
    // Lists the entries (file and directory names) in a directory.
    public fn list_dir(path String) Result<[String], FsError>
    // Creates a directory at the given path, creating missing parents as needed.
    public fn create_dir(path String) Result<bool, FsError>
    // Deletes a regular file at the given path.
    public fn delete(path String) Result<bool, FsError>
    // Returns the current working directory as an absolute path.
    public fn cwd() Result<String, FsError>
use system.ops
use system.result
// Represents an environment variable operation error.
@non_exhaustive
public enum EnvError
    InvalidName(String)
    InvalidValue(String)
    Other(String)
// Environment variable capability class. Acquire a handle with `let env = Env()`.
public class Env
    // Returns the value of an environment variable, or None if it is not set.
    public fn get(name String) String?
    // Sets an environment variable for this process and its children.
    public fn set(name String, value String) Result<bool, EnvError>
// Command-line arguments passed to the program, excluding the program path.
public class Args implements Iterable<String>
    // Returns the number of arguments, excluding the program path.
    public fn length() int
    // Returns the argument at the given 0-based index.
    public fn element_at(index int) String
// Returns the name of the host platform, such as "macos", "linux" or "windows".
public fn platform() String
use system.string
// Prints a string to stdout without a trailing newline.
public fn print(message String)
// Prints a string to stdout with a trailing newline.
public fn println(message String = "")
// Prints a string to stderr without a trailing newline.
public fn eprint(message String)
// Prints a string to stderr with a trailing newline.
public fn eprintln(message String)
// Returns the platform-specific line ending.
public fn line_end() String
// Prints a message to stderr and aborts the process immediately.
public fn panic(message String)
class String implements Equatable, Hashable, Comparable, Addable, Multiplicable, Iterable, Cloneable
    fn clone() String
    fn code_at(index int) int?
    fn compare(other String) int
    fn concat(other String) String
    fn contains(needle String) bool
    fn element_at(index int) String
    fn ends_with(suffix String) bool
    fn equals(other String) bool
    static fn from_code_point(code int) String?
    fn hash() int
    fn init() String
    fn is_empty() bool
    fn join(parts [String]) String
    fn length() int
    fn repeat(count int) String
    fn replace(old String, to String) String
    fn size() int
    fn split(separator String) [String]
    fn starts_with(prefix String) bool
    fn substring(start int, end int) String
    fn to_float() float?
    fn to_int() int?
    fn to_lower() String
    fn to_upper() String
    fn trim() String
    fn trim_end() String
    fn trim_start() String
use system.ops
use system.collections.queryable
use system.collections.list
use system.collections.transformable
use system.collections.foldable
use system.collections.sequenced
use system.memory
use system.accelerator
// A fixed-size array with elements of a single type.
public class Array<T, Size> implements Equatable, Hashable, Queryable<T>, Iterable<T>, Cloneable, Transformable<T>, Foldable<T>, Sequenced<T>, Accelerable
    // Returns the number of elements in the array (always equals Size).
    public fn length() int
    // Two arrays are equal when they hold equal elements in the same order.
    public fn equals(other Self) bool
    // A hash consistent with `equals`: arrays holding equal elements in the
    public fn hash() int
    // Returns the element at the given index.
    @index_bounds_check("index")
public fn element_at(index int) T
    // Sets the element at the given index.
    @index_bounds_check("index")
public fn set(index int, value T)
    // Sorts the array in ascending order.
    public fn sort()
    // Reverses the array in place.
    public fn reverse()
    // Returns a deep copy of this array.
    public fn clone() [T; Size]

