cd /tmp/life && cat > /tmp/ref.py <<'EOF'
import sys,random
def gen(w,h,g,seed):
    random.seed(seed)
    return [[random.randint(0,1) for _ in range(w)] for _ in range(h)]
def step(grid,w,h):
    n=[[0]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            c=sum(grid[y+dy][x+dx] for dy in(-1,0,1) for dx in(-1,0,1) if (dx or dy) and 0<=y+dy<h and 0<=x+dx<w)
            n[y][x]=1 if (c==3 or (grid[y][x] and c==2)) else 0
    return n
mode=sys.argv[1]; w,h,g,seed=map(int,sys.argv[2:6])
grid=gen(w,h,g,seed)
if mode=="gen":
    print(w,h,g)
    for r in grid: print(" ".join(map(str,r)))
else:
    for _ in range(g): grid=step(grid,w,h)
    for r in grid: print(" ".join(map(str,r)))
    print("ALIVE",sum(map(sum,grid)))
EOF
for cfg in "1 1 5 1" "7 3 0 2" "3 9 10 3" "40 30 50 4" "64 1 7 5"; do
 python3 -I /tmp/ref.py gen $cfg > t.txt; python3 -I /tmp/ref.py run $cfg > e.txt
 miri run main.mi -- t.txt > o.txt; echo "$cfg exit $?"; cmp o.txt e.txt && echo same
done
python3 -I /tmp/ref.py gen 512 512 1000 9 > big.txt
time miri run main.mi -- big.txt | tail -1

